638	/// An inner node in the untyped syntax tree.
639	#[derive(Clone, Eq, PartialEq, Hash)]
640	struct InnerNode {
641	    /// The byte length of the node in the source.
642	    len: usize,
643	    /// The number of nodes in the whole subtree, including this node.
644	    descendants: usize,
645	    /// Whether this node or any of its children contain an error/warning
646	    /// diagnostic.
647	    diagnosis: Diagnosis,
648	    /// The upper bound of this node's numbering range.
649	    upper: u64,
650	    /// This node's children, losslessly make up this node.
651	    children: Vec<SyntaxNode>,
652	}
653	
654	impl InnerNode {
655	    /// Create a new inner node with the given children.
656	    fn new(children: Vec<SyntaxNode>) -> Self {
657	        let mut len = 0;
658	        let mut descendants = 1;
659	        let mut diagnosis = Diagnosis::default();
660	
661	        for child in &children {
662	            len += child.len();
663	            descendants += child.descendants();
664	            diagnosis = diagnosis.or(child.diagnosis());
665	        }
666	
667	        Self { len, descendants, diagnosis, upper: 0, children }
668	    }
669	
670	    /// Assign span numbers `within` an interval to this node's subtree or just
671	    /// a `range` of its children.
672	    fn numberize(
673	        &mut self,
674	        span: &mut Span,
675	        id: FileId,
676	        range: Option<Range<usize>>,
677	        within: Range<u64>,
678	    ) -> NumberingResult {
679	        // Determine how many nodes we will number.
680	        let descendants = match &range {
681	            Some(range) if range.is_empty() => return Ok(()),
682	            Some(range) => self.children[range.clone()]
683	                .iter()
684	                .map(SyntaxNode::descendants)
685	                .sum::<usize>(),
686	            None => self.descendants,
687	        };
688	
689	        // Determine the distance between two neighbouring assigned numbers. If
690	        // possible, we try to fit all numbers into the left half of `within`
691	        // so that there is space for future insertions.
692	        let space = within.end - within.start;
693	        let mut stride = space / (2 * descendants as u64);
694	        if stride == 0 {
695	            stride = space / self.descendants as u64;
696	            if stride == 0 {
697	                return Err(Unnumberable);
698	            }
699	        }
700	
701	        // Number the node itself.
702	        let mut start = within.start;
703	        if range.is_none() {
704	            let end = start + stride;
705	            *span = Span::from_number(id, SpanNumber((start + end) / 2));
706	            self.upper = within.end;
707	            start = end;
708	        }
709	
710	        // Number the children.
711	        let len = self.children.len();
712	        for child in &mut self.children[range.unwrap_or(0..len)] {
713	            let end = start + child.descendants() as u64 * stride;
714	            child.numberize(id, start..end)?;
715	            start = end;
716	        }
717	
718	        Ok(())
719	    }
720	
721	    /// Whether the two inner nodes are the same apart from spans.
722	    fn spanless_eq(&self, other: &Self) -> bool {
723	        self.len == other.len
724	            && self.descendants == other.descendants
725	            && self.diagnosis == other.diagnosis
726	            && self.children.len() == other.children.len()
727	            && self
728	                .children
729	                .iter()
730	                .zip(&other.children)
731	                .all(|(a, b)| a.spanless_eq(b))
732	    }
733	
734	    /// Replaces a range of children with a replacement.
735	    ///
736	    /// May have mutated the children if it returns `Err(_)`.
737	    fn replace_children(
738	        &mut self,
739	        span: &mut Span,
740	        mut range: Range<usize>,
741	        replacement: Vec<SyntaxNode>,
742	    ) -> NumberingResult {
743	        let Some(id) = span.id() else { return Err(Unnumberable) };
744	        let mut replacement_range = 0..replacement.len();
745	
746	        // Trim off common prefix.
747	        while range.start < range.end
748	            && replacement_range.start < replacement_range.end
749	            && self.children[range.start]
750	                .spanless_eq(&replacement[replacement_range.start])
751	        {
752	            range.start += 1;
753	            replacement_range.start += 1;
754	        }
755	
756	        // Trim off common suffix.
757	        while range.start < range.end
758	            && replacement_range.start < replacement_range.end
759	            && self.children[range.end - 1]
760	                .spanless_eq(&replacement[replacement_range.end - 1])
761	        {
762	            range.end -= 1;
763	            replacement_range.end -= 1;
764	        }
765	
766	        let mut replacement_vec = replacement;
767	        let replacement = &replacement_vec[replacement_range.clone()];
768	        let superseded = &self.children[range.clone()];
769	
770	        // Compute the new byte length.
771	        self.len = self.len + replacement.iter().map(SyntaxNode::len).sum::<usize>()
772	            - superseded.iter().map(SyntaxNode::len).sum::<usize>();
773	
774	        // Compute the new number of descendants.
775	        self.descendants = self.descendants
776	            + replacement.iter().map(SyntaxNode::descendants).sum::<usize>()
777	            - superseded.iter().map(SyntaxNode::descendants).sum::<usize>();
778	
779	        // Update our diagnosis after the replacement.
780	        // - If we had no errors/warnings before, we can just use the replaced
781	        //   diagnosis
782	        // - Or, if our replacement has errors _and_ warnings, we can use that
783	        // - Otherwise, we need to update based on all of the children _outside_
784	        //   the replaced range in case we replaced the erroneous children
785	        let replaced_diagnosis = Diagnosis::any(replacement);
786	        if !self.diagnosis.either() || replaced_diagnosis.both() {
787	            self.diagnosis = replaced_diagnosis;
788	        } else {
789	            self.diagnosis = replaced_diagnosis.or(Diagnosis::or(
790	                Diagnosis::any(&self.children[..range.start]),
791	                Diagnosis::any(&self.children[range.end..]),
792	            ));
793	        }
794	
795	        // Perform the replacement.
796	        self.children
797	            .splice(range.clone(), replacement_vec.drain(replacement_range.clone()));
798	        range.end = range.start + replacement_range.len();
799	
800	        // Renumber the new children. Retries until it works, taking
801	        // exponentially more children into account.
802	        let mut left = 0;
803	        let mut right = 0;
804	        let max_left = range.start;
805	        let max_right = self.children.len() - range.end;
806	        loop {
807	            let renumber = range.start - left..range.end + right;
808	
809	            // The minimum assignable number is either
810	            // - the upper bound of the node right before the to-be-renumbered
811	            //   children,
812	            // - or this inner node's span number plus one if renumbering starts
813	            //   at the first child.
814	            let start_number = renumber
815	                .start
816	                .checked_sub(1)
817	                .and_then(|i| self.children.get(i))
818	                .map_or(span.number() + 1, |child| child.upper());
819	
820	            // The upper bound for renumbering is either
821	            // - the span number of the first child after the to-be-renumbered
822	            //   children,
823	            // - or this node's upper bound if renumbering ends behind the last
824	            //   child.
825	            let end_number = self
826	                .children
827	                .get(renumber.end)
828	                .map_or(self.upper, |next| next.span().number());
829	
830	            // Try to renumber.
831	            let within = start_number..end_number;
832	            if self.numberize(span, id, Some(renumber), within).is_ok() {
833	                return Ok(());
834	            }
835	
836	            // If it didn't even work with all children, we give up.
837	            if left == max_left && right == max_right {
838	                return Err(Unnumberable);
839	            }
840	
841	            // Exponential expansion to both sides.
842	            left = (left + 1).next_power_of_two().min(max_left);
843	            right = (right + 1).next_power_of_two().min(max_right);
844	        }
845	    }
846	
847	    /// Update this node after changes were made to one of its children.
848	    fn update_parent(
849	        &mut self,
850	        prev_len: usize,
851	        new_len: usize,
852	        prev_descendants: usize,
853	        new_descendants: usize,
854	    ) {
855	        self.len = self.len + new_len - prev_len;
856	        self.descendants = self.descendants + new_descendants - prev_descendants;
857	        self.diagnosis = Diagnosis::any(&self.children);
858	    }
859	
860	    /// Format the inner node with its `SyntaxKind` for debugging.
861	    fn debug_fmt(&self, f: &mut Formatter, kind: SyntaxKind) -> fmt::Result {
862	        write!(f, "{kind:?}: {}", self.len)?;
863	        if !self.children.is_empty() {
864	            f.write_str(" ")?;
865	            f.debug_list().entries(&self.children).finish()?;
866	        }
867	        Ok(())
868	    }
869	}
