1010	impl Debug for WarningWrapper {
1011	    fn fmt(&self, f: &mut Formatter) -> fmt::Result {
1012	        let full_text = LazyCell::new(|| {
1013	            let data = self.child.clone();
1014	            let temp_node = SyntaxNode { data, span: Span::detached() };
1015	            temp_node.full_text()
1016	        });
1017	        let debug_field = |field, message, sub_range: Option<SubRange>| {
1018	            // Inner closure has `move`, so need to explicitly capture by ref.
1019	            let full_text = &full_text;
1020	            debug(move |f| {
1021	                if let Some(sr) = sub_range {
1022	                    let selected = &full_text[sr.to_relative()];
1023	                    write!(f, "{field} @({selected:?}): {message:?}")
1024	                } else {
1025	                    write!(f, "{field}: {message:?}")
1026	                }
1027	            })
1028	        };
1029	
1030	        write!(f, "Warning: ")?;
1031	        // Use `debug_set` instead of `debug_struct` so we don't have to add a
1032	        // field name when outputting the child.
1033	        let mut out = f.debug_set();
1034	        out.entry(&debug_field("message", &self.message, self.sub_range));
1035	        for (hint, sub_range) in &self.hints {
1036	            out.entry(&debug_field("hint", hint, *sub_range));
1037	        }
1038	        out.entry(&self.child);
1039	        out.finish()
1040	    }
1041	}
